package io.github.alighaziam.eom.payment.infrastructure;
import io.github.alighaziam.eom.payment.*; import jakarta.persistence.*; import java.math.BigDecimal; import java.time.Instant; import java.util.UUID;
@Entity @Table(name="payment_intents",schema="payment") public class PaymentIntentEntity {
 @Id private UUID id; @Column(name="order_id",nullable=false) private UUID orderId; @Column(nullable=false,precision=19,scale=4) private BigDecimal amount; @Column(nullable=false,length=3) private String currency; @Enumerated(EnumType.STRING) @Column(nullable=false,length=24) private PaymentStatus status; @Column(name="idempotency_key",nullable=false,unique=true,length=120) private String idempotencyKey; @Column(name="provider_reference",length=120) private String providerReference; @Column(name="failure_reason",length=500) private String failureReason; @Column(name="created_at",nullable=false,updatable=false) private Instant createdAt; @Column(name="updated_at",nullable=false) private Instant updatedAt;
 protected PaymentIntentEntity(){} public PaymentIntentEntity(UUID id,UUID orderId,BigDecimal amount,String currency,String key,String ref,Instant now){this.id=id;this.orderId=orderId;this.amount=amount;this.currency=currency;idempotencyKey=key;providerReference=ref;status=PaymentStatus.AUTHORIZED;createdAt=now;updatedAt=now;}
 public void status(PaymentStatus s,Instant now){status=s;updatedAt=now;} public PaymentIntent toDomain(){return new PaymentIntent(id,orderId,amount,currency,status,idempotencyKey,providerReference,failureReason,createdAt,updatedAt);}
}